mapper.select:
SELECT COALESCE(a.upload_batch_id, CONCAT('legacy-', a.id)) AS batch_id, MAX(a.uploader_id) AS uploader_id, MAX(a.family_id) AS family_id, MAX(a.album_id) AS album_id, MAX(a.description) AS description, MAX(a.captured_at) AS captured_at, MAX(a.create_time) AS create_time, COUNT(*) AS asset_count FROM app_album_asset a WHERE a.is_deleted = 0 AND a.family_id = #{query.familyId} AND a.album_id = #{query.albumId} AND a.status = 1
AND a.uploader_id = #{currentUserId}
AND ( a.description LIKE CONCAT('%', #{query.keyword}, '%') )
AND COALESCE(a.captured_at, a.create_time) >= #{query.startDate} AND COALESCE(a.captured_at, a.create_time) < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY)
AND DATE_FORMAT(COALESCE(a.captured_at, a.create_time), '%Y-%m') IN
#{month}
AND a.media_type IN
#{mediaType}
GROUP BY COALESCE(a.upload_batch_id, CONCAT('legacy-', a.id)) ORDER BY MAX(COALESCE(a.captured_at, a.create_time)) DESC, MAX(a.create_time) DESC
